const messageUser = $('When chat message received').first().json.chatInput || "";
const messageLower = messageUser.toLowerCase();
const parenthesesMatch = messageUser.match(/\(([^)]+)\)/);
const persone = parenthesesMatch ? parenthesesMatch[1].trim() : null;

// === 1. Détection Ferme ===
const motsFerme = [
  "ferme", "off", "mode off", "bye", "au revoir", "ciao",
  "quitter", "arreter", "eteindre", "shutdown", "stop tout",
  "bonne nuit", "a bientot", "terminer", "fin", "exit",
  "deconnecte", "coupe", "mode veille", "sleep"
];
const contientFerme = motsFerme.some(mot => messageLower.includes(mot));

// === 2. Mot de passe ===
const motDePasse = $input.first().json.motdepasse || "";
const motdepasseexiste = messageUser === motDePasse;

// === 3. Détection Musique ===
const motsMusique = ["Récitez","chante", "lire","riche","lisez","Récitez"];
const motMusiqueTrouve = motsMusique.find(mot => messageLower.includes(mot));
const contientPlay = !!motMusiqueTrouve;
let nomChanson = null;
if (contientPlay) {
  const regex = new RegExp(motMusiqueTrouve, "i");
  const parts = messageUser.split(regex);
  if (parts.length > 1 && parts[1].trim() !== "") {
    nomChanson = parts[1].trim();
  }
}

// === 4. Détection Direction ===
const directions = ["Avancer","avant", "droite", "gauche", "derriere" , "stope", "stop"];
let directionDetectee = null;
for (const dir of directions) {
  if (messageLower.includes(dir)) {
    directionDetectee = dir;
    break;
  }
}

// === 5. Gestion de l'état (Sécurisé) ===
// On récupère l'état s'il existe, sinon on met null (ou 0 selon ton besoin) pour qu'il apparaisse dans le JSON
const etat =$input.first().json.etat;

// === 6. Inconnu ===
// Correction : si etat n'est pas défini, on vérifie quand même si l'intention est inconnue
const estInconnu = !contientFerme && !motdepasseexiste && !contientPlay && !directionDetectee; 
const directionvaribale = directionDetectee === null;

// === Intention globale ===
let intention = "inconnu";
if (contientFerme)          intention = "ferme";
else if (motdepasseexiste)  intention = "motdepasse";
else if (contientPlay)      intention = "musique";
else if (directionDetectee) intention = "direction";

return {
  contientFerme:    contientFerme,
  motdepasseexiste: motdepasseexiste,
  contientPlay:     contientPlay,
  nomChanson:       nomChanson,
  direction:        directionDetectee,
  estInconnu:       estInconnu,
  intention:        intention,
  messageOriginal:  messageUser,
  directionvaribale: directionvaribale,
  etat:             etat, // Sera affiché comme null au lieu de disparaître
  persone:          persone
};

